import type { Metadata } from "next"; import { ArticlePage } from "@/components/article-page"; import { Definition } from "@/components/ui"; export const metadata:Metadata={title:"BMI for Women",description:"How adult BMI is interpreted for women, including pregnancy, menopause, and body composition context."}; export default function Page(){return <ArticlePage path="/bmi-women" title="BMI for women: useful context for adult health" description="BMI categories are shared across adult sexes, while life stage, hormones, body composition, and personal history still matter."><Definition><strong>Answer:</strong> The standard adult BMI scale is the same for women and men. It should not be used to assess pregnancy, and it cannot measure body fat directly.</Definition><h2>Life stage changes the picture</h2><p>Pregnancy requires pregnancy-specific care rather than an adult BMI target. Menopause can affect body composition and waist distribution. These changes are normal reasons to seek individualized, non-judgmental guidance.</p><h2>Beyond the scale</h2><p>Strength, energy, sleep, blood pressure, blood sugar, and emotional wellbeing can all be meaningful signs of health. Talk with a clinician about any unexplained change in weight or appetite.</p></ArticlePage>}
